1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
10	
11	/**
12	 * Validates an owner's postcode when one is supplied, so an unacceptable value is a 400 before the
13	 * owner is ever persisted. Runs after the body has been bound and published (by {@link ValidateNewOwner}
14	 * on create / {@link ValidateOwner} on update) and before the owner is built or loaded.
15	 *
16	 * <p>Postcode is optional: a {@code null} or blank value is left untouched and accepted. When present it
17	 * must be exactly four digits; otherwise it is rejected. The city's region is derived through the single
18	 * {@link Owner#regionOf(String) city-to-region table}, and when the region is known the postcode must
19	 * fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
20	 * no known region accepts any four-digit postcode.
21	 */
22	public class ValidateOwnerPostcode {
23	
24	    /** A postcode is exactly four digits. */
25	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
26	
27	    /** Region -> inclusive {low, high} four-digit postcode range. Regions absent here accept any. */
28	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
29	            "NSW", new int[] {2000, 2099},
30	            "VIC", new int[] {3000, 3099},
31	            "QLD", new int[] {4000, 4099});
32	
33	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
34	        String postcode = request.getPostcode();
35	        if (postcode == null || postcode.isBlank()) {
36	            return; // optional when absent — request contract stays backward-compatible
37	        }
38	        if (!POSTCODE.matcher(postcode).matches()) {
